contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        c.schedule(target, value, data, predecessor, salt, delay);

        bool reverted;
        try c.cancel(id) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.getTimestamp(id) == 0 && !c.isOperationPending(id));
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        require(delay >= c.getMinDelay(), "delay too small");

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        c.schedule(target, value, data, predecessor, salt, delay);

        bool pendingBefore = c.isOperationPending(id);
        uint256 timestampBefore = c.getTimestamp(id);

        bool reverted;
        try c.cancel(id) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 timestampAfter = c.getTimestamp(id);
        bool pendingAfter = c.isOperationPending(id);

        assert(
            (reverted && pendingBefore && timestampAfter == timestampBefore && pendingAfter) ||
            (!reverted && (timestampAfter == 0 || !pendingAfter))
        );
    }

    receive() external payable {}
}

